import{_ as o,o as e,c as r,ag as a}from"./chunks/framework.Aev9KvMf.js";const g=JSON.parse('{"title":"官方查询导航域启动：只导航、只教用，不代查","description":"","frontmatter":{},"headers":[],"relativePath":"project/adr/0014-query-pages.md","filePath":"project/adr/0014-query-pages.md"}'),n={name:"project/adr/0014-query-pages.md"};function s(p,t,c,_,i,l){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="官方查询导航域启动-只导航、只教用-不代查" tabindex="-1">官方查询导航域启动：只导航、只教用，不代查 <a class="header-anchor" href="#官方查询导航域启动-只导航、只教用-不代查" aria-label="Permalink to &quot;官方查询导航域启动：只导航、只教用，不代查&quot;">​</a></h1><p>用户要求延伸到部委下属单位与官方查询页面（如卫健委政务服务平台 zwfw.nhc.gov.cn 的查询频道）。决定引入第四种内容形态<strong>查询页</strong>，并启动&quot;官方查询&quot;域。</p><p>边界（本域的立身之本）：</p><ol><li><strong>只导航 + 只教用</strong>：官方入口唯一权威链接、查询步骤、结果怎么读、避坑要点；不代查、不缓存/转存查询结果、不聚合第三方镜像入口。</li><li><strong>入口腐坏对策</strong>：每个查询页标注&quot;入口以部委官网为准&quot;，纳入半年核查节奏；链接失效立即修。</li><li><strong>白名单扩展</strong>：部委直属单位与部委运行的政务服务平台归一级来源（健康中国官方平台、国家食品安全风险评估中心、国家癌症中心/心血管病中心、卫健委政务服务平台等）；中国疾控中心维持二级。</li></ol><p>首批四篇（家庭防坑四大件）：化妆品备案/注册查询（NMPA——注意化妆品不在卫健委政务平台，属药监局）、药品批准文号查询（NMPA）、医疗机构与执业医师查询（卫健委政务平台&quot;查信息&quot;频道，已浏览器实测含执业医师/执业护士/辅助生殖机构/爱婴医院等）、保健食品注册备案查询（市场监管总局特殊食品信息查询平台）。</p><p>事实核查记录：zwfw.nhc.gov.cn/cxx/ 实测为&quot;查信息&quot;频道（浏览器验证），<strong>不含化妆品查询</strong>——化妆品属药监局体系，词条如实分流，不做迁就。</p>',6)])])}const d=o(n,[["render",s]]);export{g as __pageData,d as default};
